    ["cons_combat_pots_hint"]   = { en = "In combat, automatically highlights the highest-tier usable healing/mana potion (or healthstone) in your bags/bars below the chosen %.", pt = "Em combate, destaca automaticamente a poção de vida/mana (ou pedra de vida) mais valiosa da bolsa/barra quando cair abaixo do % escolhido." },
    ["cons_section_bonus"]      = { en = "Bonus potions & scrolls (5+ min)", pt = "Poções de bônus e pergaminhos (5+ min)" },
    ["cons_bonus_enable"]       = { en = "Recommend missing bonus potions / scrolls", pt = "Recomendar poções de bônus / pergaminhos faltantes" },
