    ["cons_bonus_scrolls"]      = { en = "Stat / armor scrolls (30 min)", pt = "Pergaminhos de atributos/armadura (30 min)" },
    ["cons_bonus_hint"]         = { en = "Compares your bags against active buffs and highlights the highest-value missing potion or scroll per category.", pt = "Compara a bolsa com seus buffs ativos e destaca a poção/pergaminho mais caro de cada tipo faltante." },
    ["cons_section_custom"]     = { en = "Situational potions & usable items", pt = "Poções situacionais e itens usáveis" },
    ["cons_add_rule"]           = { en = "+ Add item / rule", pt = "+ Adicionar item / regra" },
    ["cons_custom_empty"]       = { en = "No rules yet. Click '+ Add item / rule' to configure health/mana potions, underwater breathing, engineering bombs, or items triggered after casting an ability.", pt = "Nenhuma regra criada. Clique em '+ Adicionar item / regra' para configurar poções de vida/mana, respiração aquática, bombas de engenharia ou itens após usar uma habilidade." },
    ["cons_bag_items_header"]   = { en = "Usable items in bags", pt = "Itens usáveis na bolsa" },
    ["cons_not_in_bag"]         = { en = "not in bag", pt = "fora da bolsa" },
    ["cons_axis_combat"]        = { en = "1. Combat", pt = "1. Combate" },
    ["cons_axis_env"]           = { en = "2. Environment", pt = "2. Ambiente" },
    ["cons_axis_breath"]        = { en = "3. Breath (water)", pt = "3. Fôlego (água)" },
