    ["cons_env_underwater"]     = { en = "In water / submerged", pt = "Na água / submerso" },
    ["cons_breath_50"]          = { en = "Breath < 50%", pt = "Fôlego < 50%" },
    ["cons_breath_30"]          = { en = "Breath < 30%", pt = "Fôlego < 30%" },
