    -- Info ("i") button help popups (per tab / window)
    ["info_btn_tooltip"]        = { en = "Click for help about this tab / window", pt = "Clique para ver para que serve esta aba / janela" },
    ["info_help_suffix"]        = { en = "Help", pt = "Ajuda" },
    ["help_default"]            = { en = "This section configures options for Combat Forever Assistant. The addon only highlights recommended buttons; you always stay in control.", pt = "Esta seção configura opções do Combat Forever Assistant. O addon apenas destaca os botões recomendados; você sempre continua no controle." },
    ["help_general"]            = { en = "General addon settings.\n\n- Outdated rank warning: alerts you in chat on login if any action-bar ability has a lower rank than your spellbook.\n- Welcome messages: toggles the greeting messages printed in chat when logging in or reloading.\n- Save settings: confirms your current preferences (WoW writes SavedVariables on /reload or logout).", pt = "Configurações gerais do addon.\n\n- Aviso de rank desatualizado: avisa no chat ao entrar se alguma habilidade da barra estiver em um rank menor que o do seu livro.\n- Mensagens de boas-vindas: liga ou desliga as mensagens de boas-vindas exibidas no chat ao entrar ou dar /reload.\n- Salvar configurações: confirma suas preferências atuais (o WoW grava em disco no /reload ou ao sair)." },
    ["help_key"]                = { en = "Visual highlight and Key Button customization.\n\n- Highlight style: choose between Circle, Border, Flame, Lightning or Zoom around the recommended action button.\n- Width & Colors: adjust border thickness and choose either per-function colors (Damage, AoE, Interrupt, Defensive, Utility) or a single custom color.\n- Key Button: floating widget that shows the keybind of the recommended spell. You can lock/drag it, always show it, and adjust size, font, colors and transparency.\n- Test button: flashes a sample button to preview your settings.", pt = "Personalização do destaque visual e do Botão de Tecla.\n\n- Estilo do destaque: escolha entre Círculo, Moldura, Chama, Raio ou Zoom no botão recomendado da barra.\n- Largura e Cores: ajuste a espessura da moldura e use cores por função (Dano, Área, Interrupção, Defensivo, Utilidade) ou uma cor única.\n- Botão de Tecla: janela flutuante que mostra a tecla da habilidade recomendada. Permite travar/arrastar, exibir sempre e ajustar tamanho, fonte, cores e transparência.\n- Testar: faz um destaque de exemplo para conferir o visual." },
    ["help_assist"]             = { en = "PvP Tab Assistant (SmartTabTarget).\n\n- Automatically remaps TAB and/or SHIFT+TAB to target only enemy PLAYERS while inside PvP battlegrounds.\n- Outside battlegrounds (PvE / open world), TAB works normally.\n- Changes are deferred safely if you are in combat lockdown.", pt = "Assistente de TAB em PvP (SmartTabTarget).\n\n- Remapeia automaticamente TAB e/ou SHIFT+TAB para mirar apenas JOGADORES inimigos dentro de campos de batalha (PvP).\n- Fora de campos de batalha (PvE / mundo aberto), o TAB volta ao comportamento normal.\n- Alterações de tecla aguardam o fim do combate para evitar bloqueio da interface." },
    ["help_hunter"]             = { en = "Hunter rotation module (BM / MM / SV).\n\n- Enable/disable Hunter recommendations and choose automatic talent detection or manual spec override.\n- Open Rotation Editor: customize priority order (^/v), enable/disable skills, edit conditions (+ / -), test flashes on icons, and configure Aspects in the Extra tab.\n- Handles dead zone (Disengage), melee/ranged transitions, Hunter's Mark, Concussive Shot, pet utilities and racials.", pt = "Módulo de rotação do Caçador (BM / MM / SV).\n\n- Ativa/desativa recomendações do Hunter e permite detecção automática de talentos ou escolha manual da spec.\n- Abrir editor de rotação: reordene prioridades (^/v), ligue/desligue habilidades, edite condições (+ / -), teste o brilho no ícone e configure os Aspectos na aba Extra.\n- Trata zona morta (Fuga), transição melee/ranged, Marca do Caçador, Tiro Concussivo, pet e raciais." },
    ["help_shaman"]             = { en = "Shaman rotation module (Elemental / Enhancement).\n\n- Enable/disable Shaman recommendations and choose automatic talent detection or manual spec override.\n- Open Rotation Editor: customize priorities, toggles and conditions per character.\n- Extra buffs: independently toggle Lightning Shield, weapon imbues (Flametongue/Windfury), Strength of Earth and Mana Spring Totem.", pt = "Módulo de rotação do Xamã (Elemental / Aperfeiçoamento).\n\n- Ativa/desativa recomendações do Shaman e permite detecção automática de talentos ou escolha manual da spec.\n- Abrir editor de rotação: personalize prioridades, ativação e condições por personagem.\n- Buffs Extra: ative ou desative Escudo de Raios, encantamentos de arma (Língua de Fogo/Fúria dos Ventos), Força da Terra e Totem de Fonte de Mana." },
    ["help_druid"]              = { en = "Druid rotation module (Balance / Feral / Restoration).\n\n- Unified Feral spec: automatically adapts to your active form — Bear Form behaves as Tank and Cat Form behaves as Melee DPS (you always choose your form).\n- Open Rotation Editor: edit Balance, Feral and Restoration priorities, conditions (+ / -) and Extra buffs.\n- Extra buffs: toggle Mark of the Wild and Thorns recommendations (never asks to drop Bear/Cat form during combat).", pt = "Módulo de rotação do Druida (Equilíbrio / Feral / Restauração).\n\n- Spec Feral unificada: adapta-se automaticamente à sua forma atual — em Forma de Urso age como Tank e em Forma de Gato como DPS Melee (você escolhe a forma).\n- Abrir editor de rotação: edite prioridades e condições (+ / -) de Equilíbrio, Feral e Restauração.\n- Buffs Extra: ative/desative Marca do Indomado e Espinhos (nunca pede para sair de Urso/Gato em combate)." },
    ["help_priest"]             = { en = "Priest module (Shadow DPS / Discipline & Holy Group Healer).\n\n- Enable/disable Priest recommendations, choose automatic/manual spec, and select Group Healer mode (Automatic, Always Healer, or DPS only).\n- In Group Healer mode: outlines the portrait/card of the ally who needs help (Red = critical <= 35%, Green = heal/shield, Cyan = resurrect/dispel, Yellow = out of range). Once you click them and are in range, highlights the exact healing spell to press.\n- Open Rotation Editor: customize Shadow, Discipline, Holy, Healer (Group/Raid) and Extra buffs.", pt = "Módulo do Sacerdote (Sombra DPS / Disciplina e Sagrado Curandeiro).\n\n- Ative/desative recomendações, escolha a spec e defina o Modo Curandeiro (Automático em grupo/raide, Sempre Healer ou Apenas DPS).\n- No modo Curandeiro: contorna o retrato/quadro do aliado que precisa de ajuda (Vermelho = crítico <= 35%, Verde = cura/escudo, Ciano = reviver/dispel, Amarelo = fora de alcance). Assim que você clicar nele e estiver no alcance, destaca a magia de cura ideal.\n- Abrir editor de rotação: personalize Sombras, Disciplina, Sagrado, Healer (Grupo/Raide) e buffs Extra." },
    ["help_warrior"]            = { en = "Warrior rotation module (Arms / Fury / Protection).\n\n- Enable/disable Warrior recommendations and choose automatic talent detection or manual spec override.\n- Open Rotation Editor: customize Arms, Fury and Protection priorities, stances and conditions.\n- Extra buffs: toggle Battle Shout and stance reminders.", pt = "Módulo de rotação do Guerreiro (Armas / Fúria / Proteção).\n\n- Ativa/desativa recomendações do Warrior e permite detecção automática de talentos ou escolha manual da spec.\n- Abrir editor de rotação: personalize prioridades, posturas e condições de Armas, Fúria e Proteção.\n- Buffs Extra: configure lembretes de Brado de Batalha e posturas." },
    ["help_equipment"]          = { en = "Usable equipment item recommendations (19 gear slots).\n\n- Pick an equipped or bag item for any gear slot (e.g. trinkets, rings, helmet, boots).\n- Use [+] / [-] to set conditions for when the item should be highlighted.\n- Place the item on an action bar: CFA highlights it when ready and off cooldown, without ever equipping or clicking it automatically.", pt = "Recomendações de itens de equipamento usáveis (19 slots).\n\n- Escolha um item equipado ou da bolsa para qualquer slot (ex.: berloques, anéis, elmo, botas).\n- Use [+] / [-] para definir as condições em que o item deve brilhar.\n- Coloque o item na barra de ações: o CFA destaca o botão quando estiver pronto e fora de recarga, sem nunca equipar ou clicar automaticamente." },
    ["help_consumables"]        = { en = "Food, Water, Combat Potions, Bonus Potions & Situational Items.\n\n- Food & Water: out of combat and standing still, highlights the best usable food/water in your bags (or on your bar when bags are closed) below your chosen HP/Mana %.\n- Combat Potions: during combat, automatically highlights the highest-tier usable Healing Potion / Healthstone and Mana Potion below your chosen %.\n- Bonus potions & scrolls (5+ min): detects missing elixirs, flasks and scrolls compared to your active buffs.\n- Situational rules: add custom items (underwater breathing, bombs, or items triggered after casting an ability).", pt = "Comida, Água, Poções de Combate, Poções de Bônus e Itens Situacionais.\n\n- Comida e Água: fora de combate e parado, destaca a melhor comida/água usável na bolsa (ou na barra com a bolsa fechada) quando Vida/Mana estiver abaixo do % escolhido.\n- Poções de Combate: durante o combate, destaca automaticamente a Poção de Vida / Pedra de Vida e Poção de Mana de maior valor abaixo do % escolhido.\n- Poções de bônus e pergaminhos (5+ min): compara sua bolsa com os buffs ativos e destaca os que faltam.\n- Regras situacionais: adicione respiração aquática, bombas ou itens disparados após usar uma habilidade." },
    ["help_about"]              = { en = "Information about Combat Forever Assistant.\n\n- Shows the installed version, author, supported WoW Forever interface (16001) and useful slash commands (/cfa, /cfa status, /cfa debug, /cfa res, /cfa items, /cfa key, /cfa minimap).", pt = "Informações sobre o Combat Forever Assistant.\n\n- Mostra a versão instalada, autor, compatibilidade com o WoW Forever (Interface 16001) e comandos úteis (/cfa, /cfa status, /cfa debug, /cfa res, /cfa items, /cfa key, /cfa minimap)." },
    ["help_rotation_editor"]    = { en = "Rotation Editor window (saved per character).\n\n- Spec tabs: switch between your class specializations (and Extra tab for buffs/aspects).\n- Checkbox: enable or disable any individual ability.\n- Click the icon: flashes that ability on your action bar to test it.\n- [+] / [-]: add or remove custom conditions (combat, PvE/PvP, target, range, resource, AoE or special predicates).\n- [^] / [v]: move abilities up or down to change priority order.\n- Reset: restores the default rotation for the selected spec.", pt = "Janela do Editor de Rotação (salvo por personagem).\n\n- Abas de spec: alterne entre as especializações da sua classe (e a aba Extra para buffs/aspectos).\n- Caixa de seleção: liga ou desliga cada habilidade individualmente.\n- Clique no ícone: faz a habilidade piscar na sua barra de ações para testar.\n- [+] / [-]: adiciona ou remove condições personalizadas (combate, PvE/PvP, alvo, alcance, recurso, área ou predicados especiais).\n- [^] / [v]: sobe ou desce a habilidade para mudar a ordem de prioridade.\n- Restaurar: volta a rotação padrão da especialização selecionada." },
}

for key, pair in pairs(strings) do
    addon.L[key] = PT and pair.pt or pair.en
end
